  92   if (error.status && error.message) {
  93     return NextResponse.json({ message: error.message }, { status: error.status });
  94   }
  95 
  96   // 4. Fallback for generic/unexpected errors
  97   const message = error.message || 'An unexpected server error occurred.';
  98   const status = error.status || defaultStatus;
  99 
 100   return NextResponse.json({ message }, { status });
