 150 export async function deductUserCredits(userId: string, creditsToDeduct: number): Promise<number> {
 151   // Use a transaction to ensure atomicity
 152   return await prisma.$transaction(async (tx) => {
 153     const user = await tx.user.findUnique({
 154       where: { id: userId },
 155       select: { credits: true },
 156     });
 157 
 158     if (!user) {
 159       throw new Error('User not found');
 160     }
 161 
 162     const currentCredits = user.credits;
 163 
 164     if (currentCredits < creditsToDeduct) {
 165       throw {
 166         status: 402,
 167         message: 'Insufficient credits. Please purchase more credits to continue.',
 168       };
 169     }
 170 
 171     const newBalance = currentCredits - creditsToDeduct;
 172     await tx.user.update({
 173       where: { id: userId },
 174       data: { credits: newBalance },
 175     });
 176 
 177     return newBalance;
 178   });
 179 }
 180 
 181 export async function addUserCredits(userId: string, creditsToAdd: number): Promise<number> {
 182   const user = await prisma.user.update({
 183     where: { id: userId },
 184     data: {
 185       credits: {
 186         increment: creditsToAdd,
 187       },
 188     },
 189     select: { credits: true },
 190   });
 191 
 192   return user.credits;
 193 }
