  33     mutationFn: async (data: PasswordFormValues) => {
  34       if (!session?.user?.id) {
  35         throw new Error('User not properly authenticated.');
  36       }
  37       const response = await fetch('/api/auth/change-password', {
  38         method: 'POST',
  39         headers: { 'Content-Type': 'application/json' },
  40         body: JSON.stringify({
  41           currentPassword: data.currentPassword,
  42           newPassword: data.newPassword,
  43         }),
  44       });
  45 
  46       if (!response.ok) {
  47         const error = await response.json();
  48         throw new Error(error.error || 'Failed to change password');
  49       }
  50 
  51       return response.json();
  52     },
  53     onSuccess: () => {
  54       toast({ title: 'Success', description: 'Your password has been updated.' });
  55       form.reset();
