  77             <CardTitle>Change Password</CardTitle>
  78             <CardDescription>Update your account password.</CardDescription>
  79           </CardHeader>
  80           <CardContent className="space-y-4">
  81             <FormField
  82               control={form.control}
  83               name="currentPassword"
  84               render={({ field }) => (
  85                 <FormItem>
  86                   <FormLabel>Current Password</FormLabel>
  87                   <FormControl>
  88                     <Input type="password" {...field} disabled={changePasswordMutation.isPending} />
  89                   </FormControl>
  90                   <FormMessage />
  91                 </FormItem>
  92               )}
  93             />
  94             <FormField
  95               control={form.control}
  96               name="newPassword"
